package com.pulsefit.subscriptionservice;
import com.pulsefit.subscriptionservice.entity.*; import com.pulsefit.subscriptionservice.repo.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.time.LocalDate;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(PlanRepository plans,SubscriptionRepository subs){return args->{if(plans.count()==0){plans.save(make("Basic","Essential gym access",1,999,"One facility"));plans.save(make("Premium","Multi-facility access",3,2499,"All facilities"));plans.save(make("Annual","Best annual value",12,7999,"All facilities"));plans.save(make("Family","Family membership",12,12999,"All facilities"));} if(subs.count()==0){subs.save(sub(1L,1L,LocalDate.now().minusMonths(1),LocalDate.now().plusMonths(0),"ACTIVE",true));subs.save(sub(2L,2L,LocalDate.now().minusMonths(5),LocalDate.now().minusMonths(2),"EXPIRED",false));subs.save(sub(3L,3L,LocalDate.now().minusMonths(2),LocalDate.now().plusMonths(10),"ACTIVE",true));}};} private Plan make(String n,String d,int m,double p,String f){Plan x=new Plan();x.name=n;x.description=d;x.durationMonths=m;x.price=p;x.facilityAccess=f;x.active=true;return x;} private Subscription sub(Long m,Long p,LocalDate a,LocalDate e,String s,boolean ar){Subscription x=new Subscription();x.memberId=m;x.planId=p;x.startDate=a;x.endDate=e;x.status=s;x.autoRenew=ar;return x;} }